      setStatus('正在生成压缩包','正在整理阅读页面和备份文件，较大的记录可能需要一些时间。请不要关闭网页。');await wait(30);
      files.unshift({name:'小红书私信记录.html',data:encoder.encode(buildHtml(data,imageMap))});
      files.push({name:'messages.json',data:encoder.encode(JSON.stringify(data,null,2))},{name:'checkpoint.json',data:encoder.encode(JSON.stringify(snapshot()))},{name:'media-results.json',data:encoder.encode(JSON.stringify({success:imageMap.size,failed,pending,resources:results},null,2))},{name:'打开前请读.txt',data:encoder.encode(`请先完整解压，再打开“小红书私信记录.html”。请保留 images 文件夹。\n消息 ${data.messages.length} 条；媒体成功 ${imageMap.size}，失败 ${failed}，未完成 ${pending}。\n没有成功保存的媒体仍可能需要联网。checkpoint.json 可以恢复读取进度。`)});
