    const messages=data.messages.map(m=>{const display=pageTimePresentation(m.time,m.capturedAt||data.exportedAt);return {...m,_senderName:participants[m.sender]||usableParticipantName(m.senderLabel)||senderText(m.sender),_displayTime:display.label,_dateKey:display.dateKey,_html:`<div class="message-body">${renderRichText(m.text||'',m.emojis||[],imageMap)}</div>`+(m.cards||[]).map(c=>renderNoteCard(c,imageMap)).join('')+renderPhotos(m.images||[],imageMap)+renderVideos(m.videos||[],imageMap)+renderQuote(m.quote,imageMap)};});
